-- Демо-кабинет tutor@demo.ru (для проверяющих и показа репетиторам) наполняется
-- «живой» жизнью: решение с фото на проверке, задания с прогрессом, долг,
-- пропуск, отчёты, пробники, вопрос ученика. Только если кабинет есть
-- (миграция 0050) и ещё не наполнен; задачи — только если они есть в базе.
DO $$
DECLARE
  today_msk timestamp := date_trunc('day', now() AT TIME ZONE 'Europe/Moscow');
  has_tasks boolean := (SELECT count(*) FROM problems WHERE id IN ('p_231','p_228','rv6_lin_1','rv6_lin_2','rv6_lin_3','rv6_dist_3','rv6_dist_1')) = 7;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = 'u_review_tutor')
     OR EXISTS (SELECT 1 FROM users WHERE id = 'u_review_st3') THEN
    RETURN;
  END IF;

  -- Третий ученик: без почты (вход по логину), два проведённых занятия без оплаты — долг; один пропуск.
                     lesson_price_rub, grade, target_score)
  VALUES ('u_review_st3', 'Егор Волков', 'egor.volkov.1001@u.planimetrika.online',
          '$2a$10$b8Kq3Tta6g4FlYWIonuIr.DEfnzCoc4oIYyfeFoTH/0X0Ub5HLeCK', 'STUDENT', 'u_review_tutor', now(), now(), 2500, 10, 75);
  UPDATE users SET grade = 11 WHERE id IN ('u_review_st1', 'u_review_st2') AND grade IS NULL;


  VALUES ('sp_review_2', 'u_review_tutor', 'u_review_st2', 2000, 1, (today_msk - interval '6 days')::date, 'Перевод');

     E'Что делали: точки экстремума через производную, задание 12.\nПолучилось: находит производную и знаки без ошибок.\nПоработать над: не забывать проверять, входит ли точка в отрезок.', 'sl_review_9'),
    ('ll_review_3', 'u_review_tutor', 'u_review_st3', (today_msk - interval '5 days')::date::text, 'Логарифмы',
     E'Что делали: свойства логарифмов, простейшие уравнения.\nПолучилось: уравнения вида log_a(x) = b.\nПоработать над: ОДЗ — дважды забыл её записать.', 'sl_review_6'),
    ('ll_review_4', 'u_review_tutor', 'u_review_st1', (today_msk - interval '8 days')::date::text, 'Формулы приведения',
     E'Что делали: формулы приведения и единичная окружность.\nПолучилось: быстро упрощает выражения.\nПоработать над: знаки в III четверти.', 'sl_review_10');


  VALUES ('u_review_st3', 'u_review_tutor', 'Мама — Ирина, пишет в WhatsApp. Оплата обычно в конце месяца.')
  ON CONFLICT DO NOTHING;

  IF NOT has_tasks THEN
    RETURN;
  END IF;

  -- Задания: у Дмитрия — в работе (3 из 5), у Алины — просрочено (1 из 4).
     '["rv6_lin_1","rv6_lin_2","rv6_lin_3","rv6_dist_3","p_231"]'::jsonb, (today_msk + interval '3 days' + interval '23 hours') AT TIME ZONE 'Europe/Moscow', now() - interval '2 days'),
    ('hw_review_2', 'u_review_tutor', 'u_review_st2', 'Случайные величины', 'homework', true, 'assigned',
     '["rv6_dist_1","rv6_dist_3","rv6_lin_2","rv6_lin_3"]'::jsonb, (today_msk - interval '1 day' + interval '23 hours') AT TIME ZONE 'Europe/Moscow', now() - interval '6 days');


  -- Развёрнутое решение №14 с фото тетради — ждёт проверки.

  VALUES ('sq_review_1', 'u_review_st2', 'u_review_tutor', 'rv6_dist_1', '0.3',
          'Не понимаю, почему p не 0,3 — сумма же должна быть 1?', now() - interval '5 hours');
END $$;
